PRAGMA foreign_keys = ON;
CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', parent_id TEXT REFERENCES categories(id) ON DELETE RESTRICT, icon TEXT NOT NULL DEFAULT 'plug', sort_order INTEGER NOT NULL DEFAULT 0, visible INTEGER NOT NULL DEFAULT 1 CHECK(visible IN (0,1)), seo_title TEXT NOT NULL DEFAULT '', seo_description TEXT NOT NULL DEFAULT '', attributes TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(attributes)));
CREATE TABLE tags (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', indexable INTEGER NOT NULL DEFAULT 0);
CREATE TABLE authors (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, biography TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', links TEXT NOT NULL DEFAULT '[]', user_id TEXT);
CREATE TABLE content_records (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('article','product','page')), state TEXT NOT NULL DEFAULT 'UNPUBLISHED' CHECK(state IN ('UNPUBLISHED','PUBLISHED','ARCHIVED','TRASHED')), created_by TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT, live_revision_id TEXT REFERENCES revisions(id) DEFERRABLE INITIALLY DEFERRED, draft_revision_id TEXT REFERENCES revisions(id) DEFERRABLE INITIALLY DEFERRED, public_path TEXT UNIQUE);
CREATE TABLE revisions (id TEXT PRIMARY KEY, content_id TEXT NOT NULL REFERENCES content_records(id) ON DELETE CASCADE, workflow TEXT NOT NULL DEFAULT 'DRAFT' CHECK(workflow IN ('DRAFT','IN_REVIEW','APPROVED','SCHEDULED','PUBLISHED','SUPERSEDED')), data TEXT NOT NULL CHECK(json_valid(data)), created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX content_state_kind ON content_records(state,kind,published_at);
CREATE INDEX content_owner ON content_records(created_by,state);
CREATE INDEX revisions_content ON revisions(content_id,created_at);
CREATE TABLE settings (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL);
CREATE TABLE media_assets (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL, alt TEXT NOT NULL DEFAULT '', credit TEXT NOT NULL DEFAULT '', license TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'PRIVATE' CHECK(visibility IN ('PRIVATE','PUBLIC')), created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE redirects (id TEXT PRIMARY KEY, source TEXT NOT NULL UNIQUE, target TEXT NOT NULL, created_at TEXT NOT NULL, CHECK(source <> target));
CREATE TABLE analytics_events (id TEXT PRIMARY KEY, event_type TEXT NOT NULL CHECK(event_type IN ('page_view','affiliate_click')), article_id TEXT REFERENCES content_records(id) ON DELETE SET NULL, product_id TEXT REFERENCES content_records(id) ON DELETE SET NULL, path TEXT NOT NULL, placement TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX analytics_date ON analytics_events(created_at,event_type);
CREATE TABLE contacts (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, topic TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','READ','CLOSED')), created_at TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, work_key TEXT NOT NULL UNIQUE, content_id TEXT REFERENCES content_records(id), revision_id TEXT REFERENCES revisions(id), status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','RUNNING','DONE','FAILED','CANCELLED')), attempts INTEGER NOT NULL DEFAULT 0, scheduled_at TEXT NOT NULL, lease_until TEXT, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX jobs_due ON jobs(status,scheduled_at);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, context TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX audit_time ON audit_log(created_at);
CREATE TABLE outbox (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, created_at TEXT NOT NULL, last_error TEXT);
CREATE TABLE newsletter_subscribers (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, status TEXT NOT NULL, consent_at TEXT NOT NULL, policy_version TEXT NOT NULL, token_hash TEXT UNIQUE, token_expires TEXT, unsubscribe_hash TEXT UNIQUE);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0, reset_at INTEGER NOT NULL);
CREATE VIRTUAL TABLE public_search USING fts5(content_id UNINDEXED, title, excerpt, body, tokenize='unicode61');
